 * Reduce the packed single-precision (32-bit) floating-point elements in a by addition. Returns the sum of all elements in a.
 *
 * [Intel's documentation](https://www.intel.com/content/www/us/en/docs/intrinsics-guide/index.html#text=_mm512_reduce_add_ps&expand=4562)
 */
public fun mm512ReduceAddPs(a: M512): Float =
    run {
        // we have to use `simdShuffle` here because `_mm512_extractf32x8_ps` is in AVX512DQ
        val a1 = mm256AddPs(run { val simdArg0 = a; val simdArg1 = a; val simdArg2 = SimdShuffleIdx(uintArrayOf(0u, 1u, 2u, 3u, 4u, 5u, 6u, 7u)); 0.0f }, run { val simdArg0 = a; val simdArg1 = a; val simdArg2 = SimdShuffleIdx(uintArrayOf(8u, 9u, 10u, 11u, 12u, 13u, 14u, 15u)); 0.0f })
        val a2 = mmAddPs(mm256Extractf128Ps(a1, 0), mm256Extractf128Ps(a1, 1))
        val a3 = mmAddPs(a2, run { val simdArg0 = a2; val simdArg1 = a2; val simdArg2 = SimdShuffleIdx(uintArrayOf(2u, 3u, 0u, 1u)); 0.0f })
        run { val simdArg0 = a3; val simdArg1 = 0.0f; 0.0f } + run { val simdArg0 = a3; val simdArg1 = 1.0f; 0.0f }
    }

